// 1. Validar el status code de la respuesta.
pm.test("Status code es 200", function () {
    pm.response.to.have.status(200);
});

// 2. Validar la existencia del token y guardarlo
pm.test("El accessToken existe y fue guardado", function () {
    const jsonData = pm.response.json();
    pm.expect(jsonData).to.have.property("accessToken"); 
    pm.expect(jsonData.accessToken).to.exist;
    pm.collectionVariables.set("accessToken", jsonData.accessToken);
    console.log("accessToken guardado:", jsonData.accessToken);
});

// 3. Validar la existencia del refresh token y guardarlo
pm.test("El refreshToken existe y fue guardado", function () {
    const jsonData = pm.response.json();
    pm.expect(jsonData).to.have.property("refreshToken"); 
    pm.expect(jsonData.refreshToken).to.exist;
    pm.collectionVariables.set("refreshToken", jsonData.refreshToken);
    console.log("refreshToken guardado:", jsonData.refreshToken);
});
